sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    try {
        var busProcess = current.business_process_definition.sys_id; // current business process reference    
        var busClient = current.client.sys_id; // // current client reference    
        var checkList = new GlideRecord('x_hsb11_hsbc_mss_o_client_and_processes_checklist');
        checkList.addEncodedQuery('business_process_definition=' + busProcess + '^client=' + busClient);
        checkList.query();
        if (checkList.next()) {
            gs.info('Client and Processes Checklist record already exisits for the selected Business Process Definition and Client');
            current.setAbortAction(true); // aborting action if the Business process and client combination already exists    }
        }
    } catch (ex) {
        var message = ex.message;
        gs.log("Error from Business Rule - TBC : " + message);
    }
})(current, previous);
